{{(() => {
     // What happens at the door for the chosen "Кой плаща", priced by the server with the
     // same code as the real order (PortalQuote) - laid out like the console's box (2026-10-02).
     const en = appsmith.store.bo_lang === 'en';
     const payer = NewPaymentMethodSelect.selectedOptionValue || 'all';
     const eur = (v) => Number(v || 0).toLocaleString('bg-BG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
     if (!OrderShippingSelect.selectedOptionValue) {
       return en ? 'Choose the delivery type to see the fees' : 'Изберете вид доставка, за да видите таксите';
     }
     // No COD amount typed = no наложен платеж for the goods and no НП fee; the delivery (and
     // a declared value) still apply (Ico, 2026-10-04). Nothing is asked for.
     if (PortalQuote.isLoading) return '…';
     const q = PortalQuote.data || {};
     // A service priced by weight (TODO 50, TheBasket's Кауфланд) needs the products' weights first.
     if (q.needs_weight) return q.error;
     if (q.delivery === undefined) return '';
     const dvf = Number(q.declared_fee) > 0 ? ' · ' + (en ? 'declared value fee ' : 'обявена стойност ') + eur(q.declared_fee) : '';
     // A merchant on one НП rate for cash and another for card (2026-10-07): which one applies
     // is only known when the driver records how the recipient paid, so both are shown.
     const twoRates = q.cod_fee_card !== undefined && Number(q.cod_fee_card) !== Number(q.cod_fee);
     const pct = (v) => Number(v || 0).toLocaleString('bg-BG', { maximumFractionDigits: 2 }) + ' %';
     const feeText = twoRates
       ? (en ? 'COD fee ' : 'такса НП ') + eur(q.cod_fee) + ' (' + pct(q.cod_pct) + (en ? ' cash' : ' в брой') + ') / ' + eur(q.cod_fee_card) + ' (' + pct(q.cod_pct_card) + (en ? ' card' : ' с карта') + ')'
       : (en ? 'COD fee ' : 'такса НП ') + eur(q.cod_fee);
     const fees = (en ? 'delivery ' : 'доставка ') + eur(q.delivery) + ' · ' + feeText + dvf;
     // Fees on a monthly фактура (TheBasket's contract, 2026-10-11): the driver collects exactly
     // the НП, all of it comes back to the merchant, and our fees are on their monthly invoice.
     if (q.by_invoice) {
       const inv = (en ? 'On your monthly invoice: ' : 'Във вашата месечна фактура: ') + eur(q.invoiced) + ' (' + fees + ')';
       if (Number(q.collected) > 0) {
         return (en ? 'Total to collect: ' : 'Сума за събиране: ') + eur(q.collected) + '\n'
           + (en ? 'Paid back to you in full: ' : 'Връщаме ви изцяло: ') + eur(q.owed_to_merchant) + '\n' + inv;
       }
       return (en ? 'The driver collects nothing.' : 'Шофьорът не събира нищо.') + '\n' + inv;
     }
     if (payer === 'all' && Number(q.goods) > 0) {
       const owed = twoRates
         ? eur(q.owed_to_merchant) + (en ? ' if paid in cash / ' : ' при плащане в брой / ') + eur(q.owed_to_merchant_card) + (en ? ' by card' : ' с карта')
         : eur(q.owed_to_merchant);
       return (en ? 'Total to collect: ' : 'Сума за събиране: ') + eur(q.collected) + '\n'
         + (en ? 'COD amount (goods) ' : 'Стока (наложен платеж) ') + eur(q.goods) + ' · ' + fees
         // "You receive" hidden for МУЗЕЙ НА ИЛЮЗИИТЕ ООД only, until the card fee is settled (Ico, 2026-10-21).
         + (appsmith.store.customer_uuid === '777a2529-9f88-4733-9924-6ef729e38007' ? '' : '\n' + (en ? 'You receive ' : 'Вие получавате ') + owed);
     }
     if (payer === 'fees' || payer === 'all') {
       return (en ? 'Total to collect: ' : 'Сума за събиране: ') + eur(q.collected) + '\n'
         + (en ? 'Our fees only: ' : 'Само нашите такси: ') + fees + '\n'
         + (en ? 'No COD amount: the goods were paid to you already.' : 'Без наложен платеж: стоката е платена на вас предварително.');
     }
     // No наложен платеж: no COD amount and no percentage fee - the delivery alone (2026-10-02).
     return (en ? 'The driver collects nothing.' : 'Шофьорът не събира нищо.') + '\n'
       + (en ? 'On your weekly invoice: ' : 'Във вашата седмична фактура: ') + eur(q.invoiced)
       + ' (' + (en ? 'delivery ' : 'доставка ') + eur(q.delivery) + dvf + ')';
   })()}}
